import { useEffect } from 'react';
import { router, useIsFocused, useRootNavigationState } from 'expo-router';
import { SIGNED_IN_HOME, peekExplicitLanding } from '../../lib/auth';

// Default child of the tab group when the anchor has not loaded yet.
// Not a tab. Replaces into Events, or into a return path that was already chosen.
export default function TabsIndex() {
  const focused = useIsFocused();
  const nav = useRootNavigationState();
  useEffect(() => {
    if (!focused || !nav?.key) return;
    router.replace(peekExplicitLanding() ?? SIGNED_IN_HOME);
  }, [focused, nav?.key]);
  return null;
}
